from collections import defaultdict
# group exact orientation signatures, excluding bg6, print duplicate components
by_sig=defaultdict(list)
for col,cells in comps:
 r0=min(r for r,c in cells); c0=min(c for r,c in cells)
 sig=tuple(sorted((r-r0,c-c0) for r,c in cells))
 by_sig[sig].append((col,len(cells),(r0,c0),cells))
for sig,items in by_sig.items():
 if len(items)>1:
  print('sig',sig,[(x[0],x[1],x[2]) for x in items])

from collections import defaultdict
R,C=len(g),len(g[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if (r,c) in seen: continue
  col=g[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
  while st:
   x,y=st.pop(); cells.append((x,y))
   for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
    if 0<=a<R and 0<=b<C and (a,b) not in seen and g[a][b]==col:
     seen.add((a,b)); st.append((a,b))
  if col!=6: comps.append((col,cells))
by=defaultdict(list)
for col,cells in comps:
 r0=min(r for r,c in cells); c0=min(c for r,c in cells)
 sig=tuple(sorted((r-r0,c-c0) for r,c in cells))
 by[sig].append((col,cells))
for sig,items in by.items():
 if len(items)>1:
  print('sig',sig,'items',[(co,len(cs),(min(r for r,c in cs),min(c for r,c in cs))) for co,cs in items])

